uniform float u_alpha;

void apply_alpha() {
    gl_FragColor.a = gl_FragColor.a * u_alpha;
}


uniform vec4 u_id_color;
uniform int u_enabled;

void picking_filter() {
    if( u_enabled == 0 )
        return;
    if( gl_FragColor.a == 0.0 )
        discard;
    gl_FragColor = u_id_color;
}


vec4 null_transform_map(vec4 pos) {return pos;}

uniform vec4 u_view;

void clip() {
    vec4 pos = null_transform_map(gl_FragCoord);
    if( pos.x < u_view.x || pos.x > u_view.y ||
        pos.y < u_view.z || pos.y > u_view.w ) {
        discard;
    }
}


uniform sampler2D u_texture_1;

vec4 texture_lookup(vec2 texcoord) {
    if(texcoord.x < 0.0 || texcoord.x > 1.0 ||
    texcoord.y < 0.0 || texcoord.y > 1.0) {
        discard;
    }
    return texture2D(u_texture_1, texcoord);
}

float color_to_luminance(vec4 color) { return color.r; }


uniform sampler2D texture2D_values;

vec4 sample_label_color(float t) {
    if ((false) && (1 != int(t * 255))) {
        return vec4(0);
    }
    return texture2D(
        texture2D_values,
        vec2(0.0, t)
    );
}


vec4 chain(vec4 color) {
    float result_1 = color_to_luminance(color);
    vec4 result_2 = sample_label_color(result_1);
    return result_2;
}

vec4 null_transform_map_1(vec4 pos) {return pos;}


uniform vec2 image_size;
uniform int method;  // 0=subdivide, 1=impostor
uniform sampler2D u_texture;
varying vec2 v_texcoord;

vec4 map_local_to_tex(vec4 x) {
    // Cast ray from 3D viewport to surface of image
    // (if null_transform_map_1 does not affect z values, then this
    // can be optimized as simply null_transform_map_1.map(x) )
    vec4 p1 = null_transform_map_1(x);
    vec4 p2 = null_transform_map_1(x + vec4(0, 0, 0.5, 0));
    p1 /= p1.w;
    p2 /= p2.w;
    vec4 d = p2 - p1;
    float f = p2.z / d.z;
    vec4 p3 = p2 - d * f;

    // finally map local to texture coords
    return vec4(p3.xy / image_size, 0, 1);
}


void main()
{
    clip();


    vec2 texcoord;
    if( method == 0 ) {
        texcoord = v_texcoord;
    }
    else {
        // vertex shader outputs clip coordinates;
        // fragment shader maps to texture coordinates
        texcoord = map_local_to_tex(vec4(v_texcoord, 0, 1)).xy;
    }

    gl_FragColor = chain(texture_lookup(texcoord));

    apply_alpha();
picking_filter();

}
